import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"版本号规则","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/versioning.md","filePath":"zh/release/versioning.md"}'),r={name:"zh/release/versioning.md"};function i(l,e,s,n,c,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="版本号规则" tabindex="-1">版本号规则 <a class="header-anchor" href="#版本号规则" aria-label="Permalink to &quot;版本号规则&quot;">​</a></h1><h2 id="版本方案" tabindex="-1">版本方案 <a class="header-anchor" href="#版本方案" aria-label="Permalink to &quot;版本方案&quot;">​</a></h2><p>版本标识符是<strong>工作包阶段名称</strong>： <code>WP-14-docs_release</code>、<code>WP-13-build_system</code>... 这是项目的 SemVer 等价物：阶段名称就是兼容性契约的体现（每个工作包都是一个拥有自身功能集和门禁的发布线）。</p><p>此外，每次构建还携带：</p><ul><li><strong>构建号</strong> = 构建时的提交计数（<code>git rev-list --count HEAD</code>）- 单调递增，在 <code>uname -a</code> 和更新清单的 <code>build</code> 字段中可见。</li><li><strong>版本横幅</strong> = <code>git describe --tags</code>（或显式的 <code>OC_RELEASE_VERSION=</code> 覆盖）- 烘焙到内核横幅、uname、OTA 清单和 ISO 中。</li></ul><h2 id="各数字的含义" tabindex="-1">各数字的含义 <a class="header-anchor" href="#各数字的含义" aria-label="Permalink to &quot;各数字的含义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>示例</th><th>含义</th></tr></thead><tbody><tr><td><code>uname -a</code></td><td><code>Open Cube OS WP-13-build_system build 259</code></td><td>运行中内核的阶段 + 构建</td></tr><tr><td>update.json</td><td><code>version: WP-13-build_system, build: 259</code></td><td>已发布的清单</td></tr><tr><td>发布标签</td><td><code>WP-13-build_system</code></td><td>资源所构建自的 git 标签</td></tr><tr><td>gh-pages</td><td>下载页面中的相同两个数字</td><td>网站镜像了发布版本</td></tr></tbody></table><p>一次发布 = 一个标签 = 一个构建号 = 一个清单 = 一组覆盖本地 / 发布版本 / gh-pages / 私有镜像的 SHA256。</p><h2 id="兼容性承诺" tabindex="-1">兼容性承诺 <a class="header-anchor" href="#兼容性承诺" aria-label="Permalink to &quot;兼容性承诺&quot;">​</a></h2><ul><li>Shell 命令永不删除；增加是常态（基线上移：176 -&gt; 192 -&gt; ... -&gt; 233）。</li><li>L1 编号接口永不重新编号；新组追加。</li><li>OTA 包仅更新内核；/etc 卷内容向前携带。</li></ul><h2 id="选择下一个版本" tabindex="-1">选择下一个版本 <a class="header-anchor" href="#选择下一个版本" aria-label="Permalink to &quot;选择下一个版本&quot;">​</a></h2><p>下一个工作包的阶段名称（在开发计划中确定），<code>build</code> = 发布当天的提交计数 - 绝不手动挑选。</p>',12)])])}const b=t(r,[["render",i]]);export{_ as __pageData,b as default};
